// ==============================================================
// Sábados Extras — validar payload
// ==============================================================
// Body esperado:
// {
//   uuid: string,
//   nome: string,
//   chapa: string,
//   contrato: string,             // "SEDUC SEDE" | "DETRAN" | "TRE PB" | etc
//   sabados: string[],            // ISO YYYY-MM-DD
//   anoComp: number,
//   mesComp: number,
//   optanteVT: boolean,           // do board origem
//   vtSoVolta?: boolean           // empresa fornece Uber só ida (½ valor)
// }
// vtDia é calculado dentro deste WF a partir de contrato+funcao+flags.

const body = $json.body || {};
const sabados = Array.isArray(body.sabados) ? body.sabados.filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d)) : [];

if (sabados.length === 0) {
  return [{ json: { _statusCode: 400, _erro: 'sem_sabados', mensagem: 'Nenhum sábado extra informado.' } }];
}
if (!body.chapa) {
  return [{ json: { _statusCode: 400, _erro: 'chapa_obrigatoria', mensagem: 'Campo chapa é obrigatório.' } }];
}
if (!body.nome) {
  return [{ json: { _statusCode: 400, _erro: 'nome_obrigatorio', mensagem: 'Campo nome é obrigatório.' } }];
}
if (body.optanteVT !== true && body.optanteVT !== 'SIM' && body.optanteVT !== 'sim') {
  return [{ json: { _statusCode: 400, _erro: 'nao_optante_vt', mensagem: 'Empregado não é optante de VT — sábado extra não gera benefício.' } }];
}

const hoje = new Date();
const anoComp = Number(body.anoComp) || hoje.getFullYear();
const mesComp = Number(body.mesComp) || (hoje.getMonth() + 1);

return [{
  json: {
    _statusCode: 200,
    uuid: body.uuid || null,
    nome: String(body.nome).trim(),
    chapa: String(body.chapa).padStart(6, '0'),
    contrato: String(body.contrato || '').toUpperCase().trim(),
    sabados,
    qtdSabados: sabados.length,
    optanteVT: true,
    vtSoVolta: body.vtSoVolta === true || body.vtSoVolta === 'SIM*',
    anoComp,
    mesComp,
    nomeLike: `%${String(body.nome).trim()}%`,
    ambiente: body.ambiente || 'producao'
  }
}];

// Encontra empregado RM por chapa, extrai CPF + secao + funcao.
// VT por dia vem do board Parametros de Beneficios.
const chapaTarget = $('Validar payload').first().json.chapa;
const items = $('Consultar BEN 2 (RM)').all();
let matched = null;
function getField(obj, ...keys) { for (const k of keys) if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k]; return ''; }

for (const it of items) {
  const j = it.json;
  const linhas = Array.isArray(j) ? j : (Array.isArray(j.body) ? j.body : (Array.isArray(j.data) ? j.data : [j]));
  for (const r of linhas) {
    const chapa = String(getField(r, 'Matr\u00edcula/Chapa', 'Matricula/Chapa', 'chapa')).padStart(6, '0');
    if (chapa === chapaTarget) { matched = r; break; }
  }
  if (matched) break;
}

if (!matched) {
  return [{ json: { _statusCode: 404, _erro: 'empregado_nao_encontrado', mensagem: 'Chapa ' + chapaTarget + ' nao encontrada em BEN 2.' } }];
}

const dados = $('Validar payload').first().json;
function nomeNorm(s) { return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().trim(); }
const funcao = nomeNorm(getField(matched, 'Fun\u00e7\u00e3o', 'Funcao', 'funcao'));
const contrato = nomeNorm(dados.contrato);

function round2(n) { return Math.round(Number(n || 0) * 100) / 100; }
function num(v) { return Number(String(v || '0').replace(',', '.')) || 0; }
function valoresItemsMonday() {
  const resp = $('Buscar Valores Beneficios').first().json;
  if (Array.isArray(resp.errors) && resp.errors.length > 0) throw new Error(resp.errors.map(e => e.message).join(' | '));
  return resp?.data?.boards?.[0]?.items_page?.items || [];
}
function colTitle(cv) { return nomeNorm(cv?.column?.title || cv?.id || ''); }
function colPorTitulo(item, candidatos) {
  const alvo = candidatos.map(nomeNorm);
  for (const cv of item.column_values || []) {
    const t = colTitle(cv);
    if (alvo.some(a => t === a || t.includes(a))) return cv;
  }
  return null;
}
function valorTexto(item, candidatos) { return colPorTitulo(item, candidatos)?.text || ''; }
function valorNumero(item, candidatos) { return num(valorTexto(item, candidatos)); }
function linhaAtiva(item) {
  const t = nomeNorm(valorTexto(item, ['Ativo', 'Status', 'Habilitado']));
  return !t || ['SIM', 'ATIVO', 'TRUE', '1', 'HABILITADO', 'REALIZADO', 'DONE'].includes(t);
}
function contratoLinha(item) { return nomeNorm(valorTexto(item, ['Contrato'])); }
function regraLinha(item) { return nomeNorm(valorTexto(item, ['Regra', 'Funcao', 'Cargo'])); }
function prioridadeLinha(item) { return valorNumero(item, ['Prioridade', 'Ordem']) || 0; }
function resolverValoresBeneficios() {
  const items = valoresItemsMonday().filter(linhaAtiva);
  if (items.length === 0) return { erro: 'valores_beneficios_vazio', mensagem: 'O board de valores de beneficios nao retornou linhas ativas.' };
  const matches = [];
  for (const item of items) {
    const c = contratoLinha(item);
    const regra = regraLinha(item);
    const contratoPadrao = ['PADRAO', 'GLOBAL', '*'].includes(c);
    if (c && c !== contrato && !contratoPadrao) continue;
    const regraPadrao = !regra || ['PADRAO', 'GERAL', '*'].includes(regra);
    if (!regraPadrao && !funcao.includes(regra)) continue;
    const especificidade = (c === contrato ? 1000 : 0) + (!regraPadrao ? 100 : 0) + prioridadeLinha(item);
    matches.push({ item, especificidade });
  }
  if (matches.length === 0) return { erro: 'valores_beneficios_sem_regra', mensagem: 'Nenhuma regra ativa encontrada para contrato ' + (contrato || '(vazio)') + ' e funcao ' + (funcao || '(vazia)') + '.' };
  matches.sort((a, b) => b.especificidade - a.especificidade);
  const escolhido = matches[0].item;
  const vrDia = valorNumero(escolhido, ['VR', 'Valor VR']);
  const vtDia = valorNumero(escolhido, ['VT', 'Valor VT', 'Vale Transporte']);
  if (!vrDia && !vtDia) return { erro: 'valores_beneficios_sem_valor', mensagem: 'Regra encontrada, mas VR e VT estao vazios/zerados.' };
  const contratoTxt = valorTexto(escolhido, ['Contrato']) || contrato;
  const regraTxt = valorTexto(escolhido, ['Regra', 'Funcao', 'Cargo']);
  return { vrDia, vtDia, regraAplicada: 'Board valores - ' + contratoTxt + (regraTxt ? ' / ' + regraTxt : ''), fonteValores: 'board' };
}
function failValores(code, mensagem) { return [{ json: { _statusCode: 500, _erro: code, mensagem, acao: 'skip' } }]; }
let valoresBeneficios;
try { valoresBeneficios = resolverValoresBeneficios(); }
catch (e) { return failValores('erro_ler_valores_beneficios', e.message || 'Erro ao ler board de valores de beneficios.'); }
if (valoresBeneficios.erro) return failValores(valoresBeneficios.erro, valoresBeneficios.mensagem);
let vrDia = round2(valoresBeneficios.vrDia);
let vtDia = round2(valoresBeneficios.vtDia);
let regraAplicada = valoresBeneficios.regraAplicada;

if (dados.vtSoVolta && vtDia > 0) { vtDia = round2(vtDia / 2); regraAplicada += ' + VT so volta (1/2)'; }
const valorTotal = round2(dados.qtdSabados * vtDia);

return [{
  json: {
    ...dados,
    cpf: String(getField(matched, 'CPF', 'cpf')).replace(/D/g, ''),
    secaoRM: String(getField(matched, 'Se\u00e7\u00e3o', 'Secao', 'secao')).trim(),
    nomeEmpregado: String(getField(matched, 'Nome do Intermitente', 'nome') || dados.nome).trim(),
    funcao,
    vtDia,
    vrDia,
    regraAplicada,
    fonteValores: 'board',
    valorTotal,
    valorTotalCentavos: Math.round(valorTotal * 100)
  }
}];

// Monta payloads Caju (allowance_order VT + confirmação PIX) + valida employeeId
const caju = $('Caju buscar employee').first().json;
const _interior = (() => { try { return $('Resolver Interior').first().json.interior === true; } catch (e) { return false; } })();
const _catVT = _interior ? 'TRANSPORTATION' : 'TRANSPORTATION_VOUCHER';
const items = Array.isArray(caju.items) ? caju.items : (Array.isArray(caju) ? caju : []);
const emp = items[0] || caju;

if (!emp || !emp.employeeId) {
  return [{ json: { _statusCode: 404, _erro: 'caju_employee_nao_encontrado', mensagem: 'Empregado não encontrado no Caju pelo CPF.' } }];
}

const dados = $('Extrair CPF + Seção').first().json;
const hoje = new Date();
const dataFormatada = hoje.toLocaleDateString('pt-BR');
const nomePedidoBoleto = `INT-${dados.nomeEmpregado}-SAB-${dataFormatada}`.substring(0, 27);
const sponsorId = '5ff5cdc3-c55a-46b3-8a47-29479bf5ad35';

return [{
  json: {
    ...dados,
    employeeId: emp.employeeId,
    cpfCaju: emp.cpf,
    fullNameCaju: emp.fullName,
    sponsorId,
    payloadBoleto: {
      sponsorId,
      name: nomePedidoBoleto,
      allowances: [{
        employeeId: emp.employeeId,
        amounts: [{ category: _catVT, amount: dados.valorTotalCentavos }]
      }]
    },
    payloadConfirmarBoleto: {
      paymentStrategies: [{ paymentType: 'PIX_CODE', amount: dados.valorTotalCentavos }]
    }
  }
}];

// Monta payload pro WF6 (GERAR LANCAMENTO FINANCEIRO BENEFICIOS) — só evento 110 (VT)
const dados = $('Montar payloads Caju').first().json;
return [{
  json: {
    tipo: 'Diario',
    coligada: 3,
    anoComp: dados.anoComp,
    mesComp: dados.mesComp,
    contrato: dados.contrato,
    codSecao: dados.secaoRM,
    chapas: [dados.chapa],
    eventos: ['110'],
    ambiente: dados.ambiente || 'producao'
  }
}];

// Prepara leitura obrigatoria do board de valores de beneficios.
// Usa variavel n8n BOARD_VALORES_BENEFICIOS_ID quando existir; senao usa o board atual.
let vars = {};
try { vars = $vars || {}; } catch {}
const boardId = Number(vars.BOARD_VALORES_BENEFICIOS_ID || 18413870370) || 0;
if (!boardId) {
  return [{ json: { _statusCode: 500, _erro: 'board_valores_nao_configurado', mensagem: 'Configure BOARD_VALORES_BENEFICIOS_ID no n8n.' } }];
}
const queryValoresBeneficios = `query { boards(ids: [${boardId}]) { id name items_page(limit: 500) { items { id name column_values { id text value column { title } } } } } }`;
return [{ json: { ...$json, board_valores_beneficios_id: boardId, queryValoresBeneficios } }];
